// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
    List<List<Integer>> result = new ArrayList<>();
    if (root == null) return result;
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);
    boolean leftToRight = true;
    while (!queue.isEmpty()) {
        int size = queue.size();                 // freeze this level
        LinkedList<Integer> row = new LinkedList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            if (leftToRight) {
                row.addLast(node.val);            // natural order
            } else {
                row.addFirst(node.val);           // reversed order, O(1)
            }
            if (node.left != null) queue.offer(node.left);   // always L then R
            if (node.right != null) queue.offer(node.right);
        }
        result.add(row);
        leftToRight = !leftToRight;                // flip once per level
    }
    return result;
}

