# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

from collections import deque

def zigzagLevelOrder(self, root: TreeNode) -> list[list[int]]:
    result = []
    if root is None:
        return result
    queue = deque([root])
    left_to_right = True
    while queue:
        size = len(queue)                        # freeze this level
        row = deque()
        for _ in range(size):
            node = queue.popleft()
            if left_to_right:
                row.append(node.val)              # natural order
            else:
                row.appendleft(node.val)          # reversed order, O(1)
            if node.left is not None:
                queue.append(node.left)           # always L then R
            if node.right is not None:
                queue.append(node.right)
        result.append(list(row))
        left_to_right = not left_to_right          # flip once per level
    return result

